\begin{array}{l} \int_ {a} ^ {b} f (x) \mathrm{e} ^ {f (x)} \mathrm{d} x \int_ {a} ^ {b} \frac {1}{f (x)} \mathrm{d} x = \int_ {a} ^ {b} f (x) \mathrm{e} ^ {f (x)} \mathrm{d} x \int_ {a} ^ {b} \frac {1}{f (y)} \mathrm{d} y \\ = \iint_ {D} \frac {f (x)}{f (y)} \mathrm{e} ^ {f (x)} \mathrm{d} x \mathrm{d} y = \iint_ {D} \frac {f (y)}{f (x)} \mathrm{e} ^ {f (y)} \mathrm{d} x \mathrm{d} y. \\ = \frac {1}{2} \iint_ {D} \left[ \frac {f (x)}{f (y)} \mathrm{e} ^ {f (x)} + \frac {f (y)}{f (x)} \mathrm{e} ^ {f (y)} \right] \mathrm{d} x \mathrm{d} y \\ \geqslant \iint_ {D} \mathrm{e} ^ {\frac {f (x) + f (y)}{2}} \mathrm{d} x \mathrm{d} y \geqslant \iint_ {D} \left[ 1 + \frac {f (x) + f (y)}{2} \right] \mathrm{d} x \mathrm{d} y. \\ = (b - a) ^ {2} + \int_ {a} ^ {b} f (x) \mathrm{d} x \int_ {a} ^ {b} \mathrm{d} y = (b - a) (b - a + A). \end{array}
